"""Tests for tasks_api.models (Tag, Task, TaskStatus, TaskPriority, is_overdue)."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


# ── TaskStatus / TaskPriority enums ──────────────────────────────────

class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_string_enum(self):
        assert TaskStatus("pending") is TaskStatus.PENDING
        assert TaskStatus("done") is TaskStatus.DONE


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(TaskPriority.MEDIUM)
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(TaskPriority.LOW)


# ── Tag ──────────────────────────────────────────────────────────────

class TestTag:
    def test_normalization(self):
        tag = Tag("  Hello  ")
        assert tag.name == "hello"

    def test_allows_hyphens_and_underscores(self):
        tag = Tag("my-tag_2")
        assert tag.name == "my-tag_2"

    def test_empty_name_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="must not be empty"):
            Tag("   ")

    def test_non_string_raises(self):
        with pytest.raises(TypeError, match="must be a string"):
            Tag(123)  # type: ignore[arg-type]

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters"):
            Tag("a" * 33)

    def test_max_length_ok(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    def test_illegal_character_raises(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("hello world")

    def test_illegal_character_special(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("tag@name")


# ── Task.is_overdue ──────────────────────────────────────────────────

class TestTaskIsOverdue:
    def _make(self, *, status=TaskStatus.PENDING, due_at=None):
        return Task(id=1, title="t", status=status, due_at=due_at,
                    created_at=datetime(2025, 1, 1, tzinfo=timezone.utc))

    def test_no_due_date(self, now):
        assert not self._make().is_overdue(now)

    def test_future_due_date(self, now):
        t = self._make(due_at=now + timedelta(hours=1))
        assert not t.is_overdue(now)

    def test_past_due_date(self, now):
        t = self._make(due_at=now - timedelta(hours=1))
        assert t.is_overdue(now)

    def test_done_task_not_overdue(self, now):
        t = self._make(status=TaskStatus.DONE, due_at=now - timedelta(hours=1))
        assert not t.is_overdue(now)

    def test_due_at_exactly_now_not_overdue(self, now):
        t = self._make(due_at=now)
        assert not t.is_overdue(now)

"""Tests for tasks_api.queries (TaskQuery, TaskPage, apply_query)."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, tags=None, created_at=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


# ── TaskQuery validation ─────────────────────────────────────────────

class TestTaskQuery:
    def test_defaults(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    def test_invalid_sort(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    def test_invalid_limit_zero(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=0)

    def test_invalid_limit_too_high(self):
        with pytest.raises(TaskQueryError, match="limit"):
            TaskQuery(limit=101)

    def test_invalid_offset_negative(self):
        with pytest.raises(TaskQueryError, match="offset"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  FOO  ")
        assert q.tag == "foo"

    def test_invalid_tag(self):
        with pytest.raises(ValueError):
            TaskQuery(tag="bad tag!")

    def test_search_whitespace_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"


# ── TaskPage.has_more ────────────────────────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        p = TaskPage(items=[_task(1)], total=5, limit=1, offset=0)
        assert p.has_more is True

    def test_has_more_false_exact_fit(self):
        p = TaskPage(items=[_task(1)], total=1, limit=10, offset=0)
        assert p.has_more is False

    def test_has_more_false_last_page(self):
        p = TaskPage(items=[_task(1)], total=3, limit=1, offset=2)
        assert p.has_more is False


# ── apply_query: filtering ───────────────────────────────────────────

class TestApplyQueryFiltering:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Buy milk", status=TaskStatus.PENDING, tags=[Tag("shopping")],
                  due_at=NOW - timedelta(hours=1)),
            _task(2, "Write report", status=TaskStatus.DONE, tags=[Tag("work")]),
            _task(3, "Read book", status=TaskStatus.PENDING, tags=[Tag("personal")]),
        ]

    def test_filter_by_status_pending(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING), NOW)
        assert len(page.items) == 2

    def test_filter_by_status_done(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 1

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="milk"), NOW)
        assert [t.id for t in page.items] == [1]

    def test_search_case_insensitive(self, tasks):
        page = apply_query(tasks, TaskQuery(search="REPORT"), NOW)
        assert len(page.items) == 1

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        assert len(page.items) == 1
        assert page.items[0].id == 1

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        ids = {t.id for t in page.items}
        assert 1 not in ids  # task 1 IS overdue, so excluded
        assert 2 in ids
        assert 3 in ids

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 3

    def test_combined_filters(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.PENDING, search="milk"), NOW)
        assert len(page.items) == 1


# ── apply_query: sorting ─────────────────────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Banana", priority=TaskPriority.LOW,
                  created_at=NOW - timedelta(hours=2),
                  due_at=NOW + timedelta(days=2)),
            _task(2, "Apple", priority=TaskPriority.HIGH,
                  created_at=NOW - timedelta(hours=1),
                  due_at=NOW + timedelta(days=1)),
            _task(3, "Cherry", priority=TaskPriority.MEDIUM,
                  created_at=NOW),
        ]

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 2, 3]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        assert [t.id for t in page.items] == [3, 2, 1]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Apple", "Banana", "Cherry"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.priority for t in page.items] == [
            TaskPriority.HIGH, TaskPriority.MEDIUM, TaskPriority.LOW,
        ]

    def test_sort_by_due_at_none_last(self, tasks):
        # task 3 has no due_at → should sort last in ascending
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert page.items[-1].id == 3

    def test_sort_by_due_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert page.items[0].id == 2  # soonest due
        assert page.items[1].id == 1


# ── apply_query: pagination ──────────────────────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_task(i, f"task-{i}") for i in range(1, 11)]  # 10 tasks

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3), NOW)
        assert len(page.items) == 3
        assert page.total == 10
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=8), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

    def test_offset_beyond(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=5, offset=20), NOW)
        assert len(page.items) == 0
        assert page.total == 10
        assert page.has_more is False

    def test_full_page(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=100), NOW)
        assert len(page.items) == 10
        assert page.has_more is False

"""Tests for tasks_api.repository (InMemoryTaskRepository, normalize_tags)."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags


class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def _make(self, id=1, title="Test"):
        return Task(id=id, title=title)

    def test_add_and_get(self, repo):
        t = self._make()
        repo.add(t)
        assert repo.get(1) is t

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_raises(self, repo):
        repo.add(self._make(1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(self._make(1))

    def test_list_returns_snapshot(self, repo):
        repo.add(self._make(1, "A"))
        repo.add(self._make(2, "B"))
        items = list(repo.list())
        assert len(items) == 2

    def test_update(self, repo):
        repo.add(self._make(1, "Old"))
        task = repo.get(1)
        task.title = "New"
        repo.update(task)
        assert repo.get(1).title == "New"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(self._make(99))

    def test_delete(self, repo):
        repo.add(self._make(1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2
        assert repo.next_id() == 3


class TestNormalizeTags:
    def test_dedup(self):
        result = normalize_tags([Tag("foo"), Tag("FOO"), Tag("bar")])
        assert [t.name for t in result] == ["foo", "bar"]

    def test_strings_converted(self):
        result = normalize_tags(["Hello", "world"])
        assert all(isinstance(t, Tag) for t in result)
        assert result[0].name == "hello"

    def test_mixed_input(self):
        result = normalize_tags([Tag("a"), "B", Tag("b")])
        assert [t.name for t in result] == ["a", "b"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_invalid_string_raises(self):
        with pytest.raises(ValueError):
            normalize_tags(["bad tag!"])
